using BuildMind.Infrastructure.Persistence;
using BuildMind.Persistence.IntegrationTests.Support;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using MySql.Data.MySqlClient;
using Xunit.Abstractions;
using BuildMind.Infrastructure.Persistence.Connections;

namespace BuildMind.Persistence.IntegrationTests;

/// <summary>
/// BE-M4-D03 migration validation for the PRODUCTION <see cref="BuildMindDbContext"/> on disposable databases.
/// The reviewed migrations are committed and never regenerated by CI (the tooling step only verifies
/// <c>has-pending-model-changes</c>). The sequence is exact and ordered:
/// <list type="number">
/// <item><c>20261118133137_InitialFeatureSchema</c> (STEP 06-E3): users, projects, requirement revisions/heads;</item>
/// <item><c>20261119092022_AddProjectAuthorizationVersion</c> (M1): <c>projects.authorization_version</c>;</item>
/// <item><c>20261120202215_AddSessionSecurity</c> (M4, STEP 05 decisions 1-3/7): <c>users.token_version</c>,
/// <c>refresh_tokens</c>, <c>password_reset_tokens</c>;</item>
/// <item><c>AddPlanRevisionHistory</c> (M4 STEP 22): plans and immutable revision snapshots.</item>
/// </list>
/// Every step must apply, roll back only its own changes, and reapply. These tests FAIL (never skip) when no
/// migration exists.
/// </summary>
public sealed class BuildMindMigrationTests(ITestOutputHelper output)
{
    private const string InitialFeatureSchema = "20261118133137_InitialFeatureSchema";
    private const string AddProjectAuthorizationVersion = "20261119092022_AddProjectAuthorizationVersion";
    private const string AddSessionSecurity = "20261120202215_AddSessionSecurity";

    private const string AddPlanRevisionHistory = "20261122080431_AddPlanRevisionHistory";
    private static readonly string[] M4Migrations = [InitialFeatureSchema, AddProjectAuthorizationVersion, AddSessionSecurity, AddPlanRevisionHistory];

    // Captain full-backend completion (feature/captain-full-backend-completion): additive feature migrations applied
    // after the M4 baseline. Each entry lists the tables it creates and the foreign keys (with delete rule) it adds.
    internal static readonly (string Migration, string[] Tables, string[] ForeignKeys)[] CaptainMigrations =
    [
        ("20261124095515_AddSurveys", ["surveys"],
            ["fk_surveys_projects_project_id=RESTRICT", "fk_surveys_users_uploaded_by=RESTRICT"]),
        ("20261124104612_AddCaptainPlanningWorkflow",
            ["generation_candidates", "generation_jobs", "land_revisions", "plan_validation_evidence"],
            ["fk_generation_candidates_generation_jobs=RESTRICT", "fk_generation_candidates_projects_project_id=RESTRICT",
             "fk_generation_jobs_land_revisions=RESTRICT", "fk_generation_jobs_projects_project_id=RESTRICT",
             "fk_generation_jobs_users_requested_by=RESTRICT", "fk_land_revisions_projects_project_id=RESTRICT",
             "fk_land_revisions_users_created_by=RESTRICT", "fk_plan_validation_evidence_projects_project_id=RESTRICT"]),
        ("20261124112814_AddCaptainPlanLifecycle", ["plan_confirmations", "plan_edit_candidates"],
            ["fk_plan_confirmations_plan_revisions=RESTRICT", "fk_plan_confirmations_users_confirmed_by=RESTRICT",
             "fk_plan_edit_candidates_plan_validation_evidence=RESTRICT", "fk_plan_edit_candidates_plans=RESTRICT",
             "fk_plan_edit_candidates_users_owner_id=RESTRICT"]),
        ("20261124114516_AddGenerationEvidencePackId", [], []),
        ("20261124120204_AddCaptainDeliverables", ["architect_requests", "reports"],
            ["fk_architect_requests_projects_project_id=RESTRICT", "fk_architect_requests_reports=RESTRICT",
             "fk_architect_requests_users_granted_by=RESTRICT", "fk_reports_plan_confirmations=RESTRICT",
             "fk_reports_projects_project_id=RESTRICT", "fk_reports_users_requested_by=RESTRICT"]),
        ("20261124170241_AddSurveyExtraction", ["survey_extractions"],
            ["fk_survey_extractions_projects_project_id=RESTRICT", "fk_survey_extractions_surveys=RESTRICT"]),
        ("20261124182132_AddAdministration", ["admin_audit_chain_head", "admin_audit_events", "principal_roles", "staff_change_proposals", "staff_profiles", "staff_task_notes", "staff_tasks", "system_policies"],
            ["fk_admin_audit_events_users_actor_id=RESTRICT", "fk_principal_roles_users_granted_by=RESTRICT", "fk_principal_roles_users_revoked_by=RESTRICT", "fk_principal_roles_users_user_id=RESTRICT", "fk_staff_change_proposals_users_proposed_by=RESTRICT", "fk_staff_change_proposals_users_reviewed_by=RESTRICT", "fk_staff_profiles_users_created_by=RESTRICT", "fk_staff_profiles_users_user_id=RESTRICT", "fk_staff_task_notes_staff_tasks_task_id=RESTRICT", "fk_staff_task_notes_users_author_id=RESTRICT", "fk_staff_tasks_projects_project_id=RESTRICT", "fk_staff_tasks_users_assigned_to=RESTRICT", "fk_staff_tasks_users_created_by=RESTRICT", "fk_system_policies_users_updated_by=RESTRICT"]),
        ("20261124184000_AddAccountSecurity", ["account_security", "security_events"],
            ["fk_account_security_users_user_id=RESTRICT", "fk_security_events_users_user_id=RESTRICT"]),
    ];

    private static readonly string[] ExpectedMigrations = [.. M4Migrations, .. CaptainMigrations.Select(m => m.Migration)];

    private static readonly string[] InitialTables = ["project_requirement_heads", "projects", "requirement_revisions", "users"];

    private static readonly string[] SessionSecurityTables =
        ["password_reset_tokens", "project_requirement_heads", "projects", "refresh_tokens", "requirement_revisions", "users"];

    private static readonly string[] M4Tables =
        ["password_reset_tokens", "plan_revisions", "plans", "project_requirement_heads", "projects", "refresh_tokens", "requirement_revisions", "users"];

    private static readonly string[] Tables =
        [.. M4Tables.Concat(CaptainMigrations.SelectMany(m => m.Tables)).Order(StringComparer.Ordinal)];

    [Fact]
    public async Task M01_migrations_exist_in_order_and_match_the_model()
    {
        await using var database = await DisposableMySqlDatabase.CreateAsync();
        await using var context = CreateContext(database.ConnectionString);

        var migrations = context.Database.GetMigrations().ToArray();
        output.WriteLine("Migrations: " + string.Join(", ", migrations));

        Assert.Equal(ExpectedMigrations, migrations);
        Assert.False(context.Database.HasPendingModelChanges());
    }

    [Fact]
    public async Task M02_migrations_create_the_reviewed_schema_and_history()
    {
        await using var database = await DisposableMySqlDatabase.CreateAsync();
        await using var context = CreateContext(database.ConnectionString);

        await context.Database.MigrateAsync();

        Assert.Equal(ExpectedMigrations, await context.Database.GetAppliedMigrationsAsync());
        Assert.Equal(Tables, await FeatureTablesAsync(database));

        var deleteRules = await ListAsync(database,
            "SELECT CONCAT(constraint_name, '=', delete_rule) FROM information_schema.referential_constraints WHERE constraint_schema = DATABASE() ORDER BY constraint_name;");
        output.WriteLine("FK delete rules: " + string.Join(", ", deleteRules));
        // InnoDB's implicit NO ACTION and explicit RESTRICT both reject deletion of a referenced row.
        Assert.Contains(deleteRules, rule => rule is "fk_plan_revisions_parent=NO ACTION" or "fk_plan_revisions_parent=RESTRICT");
        Assert.Equal(
            new[]
            {
                "fk_password_reset_tokens_users_user_id=RESTRICT",
                "fk_plan_revisions_plans=RESTRICT",
                "fk_plans_plan_revisions_head=RESTRICT",
                "fk_plans_projects=RESTRICT",
                "fk_project_requirement_heads_projects_project_id=RESTRICT",
                "fk_project_requirement_heads_requirement_revisions_current=RESTRICT",
                "fk_projects_users_owner_id=RESTRICT",
                "fk_refresh_tokens_users_user_id=RESTRICT",
                "fk_requirement_revisions_projects_project_id=RESTRICT",
            }.Concat(CaptainMigrations.SelectMany(m => m.ForeignKeys)).Order(StringComparer.Ordinal),
            deleteRules.Where(rule => !rule.StartsWith("fk_plan_revisions_parent=", StringComparison.Ordinal)));

        var indexes = await ListAsync(database,
            "SELECT DISTINCT CONCAT(table_name, '.', index_name, '=', non_unique) FROM information_schema.statistics WHERE table_schema = DATABASE() AND index_name <> 'PRIMARY' ORDER BY 1;");
        output.WriteLine("Indexes: " + string.Join(", ", indexes));
        Assert.Contains("users.ux_users_normalized_email=0", indexes);
        Assert.Contains("requirement_revisions.ux_requirement_revisions_project_id_revision_number=0", indexes);
        Assert.Contains("projects.ix_projects_owner_id_created_at_utc=1", indexes);
        Assert.Contains("refresh_tokens.ux_refresh_tokens_token_hash=0", indexes);
        Assert.Contains("refresh_tokens.ix_refresh_tokens_user_id=1", indexes);
        Assert.Contains("refresh_tokens.ix_refresh_tokens_family_id=1", indexes);
        Assert.Contains("plans.ix_plans_head_revision=1", indexes);
        Assert.Contains("plan_revisions.ix_plan_revisions_parent=1", indexes);
        Assert.Contains("plan_revisions.ux_plan_revisions_version=0", indexes);
        Assert.Equal("mediumtext", await ColumnTypeAsync(database, "plan_revisions", "geometry_json"));
        Assert.Equal("varbinary(32)", await ColumnTypeAsync(database, "plan_revisions", "geometry_hash"));
        Assert.Equal("varbinary(32)", await ColumnTypeAsync(database, "plan_revisions", "validation_geometry_hash"));
        Assert.Equal("tinyint(1)|YES|NULL", await ColumnShapeAsync(database, "plan_revisions", "requirements_match"));

        // One outstanding reset token per user: the primary key is the user id.
        Assert.Equal(new[] { "user_id" }, await ListAsync(database,
            "SELECT column_name FROM information_schema.key_column_usage WHERE table_schema = DATABASE() AND table_name = 'password_reset_tokens' AND constraint_name = 'PRIMARY';"));

        Assert.Equal("json", await ColumnTypeAsync(database, "requirement_revisions", "content_json"));
        foreach (var (table, column) in new[]
                 {
                     ("users", "created_at_utc"), ("projects", "created_at_utc"), ("projects", "updated_at_utc"),
                     ("requirement_revisions", "created_at_utc"),
                     ("refresh_tokens", "created_at_utc"), ("refresh_tokens", "expires_at_utc"), ("refresh_tokens", "absolute_expires_at_utc"),
                     ("password_reset_tokens", "created_at_utc"), ("password_reset_tokens", "expires_at_utc"),
                     ("plan_revisions", "created_at_utc"), ("plan_revisions", "validated_at_utc"),
                 })
        {
            Assert.Equal("datetime(6)", await ColumnTypeAsync(database, table, column));
        }

        foreach (var (table, column) in new[] { ("refresh_tokens", "token_hash"), ("password_reset_tokens", "token_hash") })
        {
            Assert.Equal("char(64)", await ColumnTypeAsync(database, table, column)); // SHA-256 hex only, never raw tokens
        }

        foreach (var (table, column) in new[] { ("users", "token_version"), ("projects", "authorization_version") })
        {
            Assert.Equal("bigint|NO|1", await ColumnShapeAsync(database, table, column));
        }
    }

    [Fact]
    public async Task M03_each_migration_rolls_back_only_its_own_changes_and_reapplies()
    {
        await using var database = await DisposableMySqlDatabase.CreateAsync();
        await using var context = CreateContext(database.ConnectionString);
        var migrator = context.GetService<IMigrator>();

        await migrator.MigrateAsync();
        Assert.Equal(Tables, await FeatureTablesAsync(database));

        // Existing account data must survive removal of the session-security schema.
        var userId = Guid.NewGuid().ToString("D");
        await ExecuteAsync(database,
            $"INSERT INTO users (id, email, normalized_email, password_hash, is_active, created_at_utc, token_version) VALUES ('{userId}', 'rollback@example.invalid', 'ROLLBACK@EXAMPLE.INVALID', 'synthetic-hash', 1, UTC_TIMESTAMP(6), 1);");

        // Captain feature migrations roll back to exactly the M4 baseline schema.
        await migrator.MigrateAsync(AddPlanRevisionHistory);
        Assert.Equal(M4Tables, await FeatureTablesAsync(database));
        Assert.Equal(M4Migrations, await context.Database.GetAppliedMigrationsAsync());

        await migrator.MigrateAsync(AddSessionSecurity);
        Assert.Equal(SessionSecurityTables, await FeatureTablesAsync(database));
        Assert.Equal(M4Migrations[..^1], await context.Database.GetAppliedMigrationsAsync());
        Assert.Equal(new[] { userId }, await ListAsync(database, "SELECT id FROM users;"));
        await migrator.MigrateAsync(AddPlanRevisionHistory);
        Assert.Equal(M4Tables, await FeatureTablesAsync(database));

        await migrator.MigrateAsync(AddProjectAuthorizationVersion);
        Assert.Equal(InitialTables, await FeatureTablesAsync(database));
        Assert.Null(await ColumnTypeAsync(database, "users", "token_version"));
        Assert.Equal("bigint", await ColumnTypeAsync(database, "projects", "authorization_version"));
        Assert.Equal(new[] { InitialFeatureSchema, AddProjectAuthorizationVersion }, await context.Database.GetAppliedMigrationsAsync());
        Assert.Equal(new[] { userId }, await ListAsync(database, "SELECT id FROM users;"));

        await migrator.MigrateAsync(InitialFeatureSchema);
        Assert.Equal(InitialTables, await FeatureTablesAsync(database));
        Assert.Null(await ColumnTypeAsync(database, "projects", "authorization_version"));
        Assert.Equal(new[] { InitialFeatureSchema }, await context.Database.GetAppliedMigrationsAsync());
        Assert.Equal(new[] { userId }, await ListAsync(database, "SELECT id FROM users;"));

        await migrator.MigrateAsync(Migration.InitialDatabase);
        Assert.Empty(await FeatureTablesAsync(database));
        Assert.Empty(await context.Database.GetAppliedMigrationsAsync());

        await migrator.MigrateAsync();
        Assert.Equal(Tables, await FeatureTablesAsync(database));
        Assert.Equal(ExpectedMigrations, await context.Database.GetAppliedMigrationsAsync());
        Assert.Equal("bigint|NO|1", await ColumnShapeAsync(database, "users", "token_version"));
    }

    [Fact]
    public async Task M04_reviewed_ranged_script_deploys_the_schema_once()
    {
        await using var database = await DisposableMySqlDatabase.CreateAsync();
        await using var context = CreateContext(database.ConnectionString);
        var migrator = context.GetService<IMigrator>();

        var script = migrator.GenerateScript(Migration.InitialDatabase, context.Database.GetMigrations().Last());
        Assert.DoesNotContain("IF NOT EXISTS(SELECT", script, StringComparison.Ordinal); // ranged, not idempotent

        await ExecuteScriptAsync(database, script);

        Assert.Equal(Tables, await FeatureTablesAsync(database));
        Assert.Equal(ExpectedMigrations, await context.Database.GetAppliedMigrationsAsync());
        Assert.Empty(await context.Database.GetPendingMigrationsAsync());
    }

    [Fact]
    public async Task M05_incremental_ranged_script_upgrades_an_initial_schema_database()
    {
        // The deployment path for an environment already at InitialFeatureSchema: a reviewed ranged script that adds
        // only the later migrations and keeps existing rows.
        await using var database = await DisposableMySqlDatabase.CreateAsync();
        await using var context = CreateContext(database.ConnectionString);
        var migrator = context.GetService<IMigrator>();
        await migrator.MigrateAsync(InitialFeatureSchema);
        var userId = Guid.NewGuid().ToString("D");
        await ExecuteAsync(database,
            $"INSERT INTO users (id, email, normalized_email, password_hash, is_active, created_at_utc) VALUES ('{userId}', 'upgrade@example.invalid', 'UPGRADE@EXAMPLE.INVALID', 'synthetic-hash', 1, UTC_TIMESTAMP(6));");

        var script = migrator.GenerateScript(InitialFeatureSchema, AddPlanRevisionHistory);
        Assert.DoesNotContain("CREATE TABLE `users`", script, StringComparison.Ordinal);
        Assert.DoesNotContain("IF NOT EXISTS(SELECT", script, StringComparison.Ordinal);

        await ExecuteScriptAsync(database, script);

        Assert.Equal(M4Tables, await FeatureTablesAsync(database));
        Assert.Equal(M4Migrations, await context.Database.GetAppliedMigrationsAsync());
        // Existing users receive the column default (token_version = 1): no data fix is needed after the upgrade.
        Assert.Equal(new[] { "1" }, await ListAsync(database, $"SELECT token_version FROM users WHERE id = '{userId}';"));
    }

    internal static BuildMindDbContext CreateContext(string connectionString)
    {
        var builder = new DbContextOptionsBuilder<BuildMindDbContext>();
        MySqlContextOptions.Apply(builder, connectionString, 60);
        return new BuildMindDbContext(builder.Options);
    }

    private static async Task<string[]> FeatureTablesAsync(DisposableMySqlDatabase database) =>
        [.. await ListAsync(database,
            "SELECT table_name FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name <> '__EFMigrationsHistory' ORDER BY table_name;")];

    private static async Task<string?> ColumnTypeAsync(DisposableMySqlDatabase database, string table, string column) =>
        (await ListAsync(database,
            $"SELECT column_type FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = '{table}' AND column_name = '{column}';"))
        .SingleOrDefault();

    private static async Task<string?> ColumnShapeAsync(DisposableMySqlDatabase database, string table, string column) =>
        (await ListAsync(database,
            $"SELECT CONCAT(column_type, '|', is_nullable, '|', COALESCE(column_default, 'NULL')) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = '{table}' AND column_name = '{column}';"))
        .SingleOrDefault();

    private static async Task ExecuteScriptAsync(DisposableMySqlDatabase database, string script)
    {
        await using var connection = new MySqlConnection(database.ConnectionString);
        await MySqlConnectionOpenGate.OpenAsync(connection);
        await new MySqlScript(connection, script).ExecuteAsync();
    }

    private static async Task ExecuteAsync(DisposableMySqlDatabase database, string sql)
    {
        await using var connection = new MySqlConnection(database.ConnectionString);
        await MySqlConnectionOpenGate.OpenAsync(connection);
        await using var command = new MySqlCommand(sql, connection);
        await command.ExecuteNonQueryAsync();
    }

    private static async Task<List<string>> ListAsync(DisposableMySqlDatabase database, string sql)
    {
        await using var connection = new MySqlConnection(database.ConnectionString);
        await MySqlConnectionOpenGate.OpenAsync(connection);
        await using var command = new MySqlCommand(sql, connection);
        await using var reader = await command.ExecuteReaderAsync();
        var values = new List<string>();
        while (await reader.ReadAsync())
        {
            values.Add(Convert.ToString(reader.GetValue(0), System.Globalization.CultureInfo.InvariantCulture)!);
        }

        return values;
    }
}
